SELECT /* getComplaintList */
FROM ( SELECT Q.CMPL_NUMB , Q.USER_NUMB , Q.REPORTER_NICK , Q.TAGT_TYPE , Q.TAGT_TYPE_NAME , Q.TAGT_NUMB , Q.TAGT_HASH , Q.TAGT_USER , Q.TAGT_CNTN , Q.EVIDENCE_AVAILABLE , Q.TARGET_USER_NICK , Q.CMPL_RSON , Q.CMPL_RSON_NAME , Q.CMPL_CNTN , Q.CMPL_STAT , Q.CMPL_STAT_NAME , Q.PROC_CNTN , Q.PROC_ADMN , Q.PROC_ADMN_NAME , Q.AUTO_ACTIONED , Q.PROC_DATE , Q.REGI_DATE , Q.UPDT_DATE , ROW_NUMBER() OVER ( ORDER BY Q.REGI_DATE DESC , Q.CMPL_NUMB DESC ) AS ROW_NUMB FROM ( SELECT , CASE WHEN C.CMPL_STAT = #{cmplActioned} AND C.PROC_ADMN IS NULL AND A.ACTN_NUMB IS NOT NULL THEN 1 ELSE 0 END AS AUTO_ACTIONED FROM TH_CMPLNT C LEFT JOIN TM_USERXM R ON R.USER_NUMB = C.USER_NUMB LEFT JOIN TM_USERXM T ON T.USER_NUMB = C.TAGT_USER LEFT JOIN ( SELECT H.TAGT_TYPE , H.TAGT_NUMB , H.TAGT_HASH , MAX(H.ACTN_NUMB) AS ACTN_NUMB FROM TH_CMACTN H GROUP BY H.TAGT_TYPE , H.TAGT_NUMB , H.TAGT_HASH ) A ON A.TAGT_TYPE = C.TAGT_TYPE AND A.TAGT_NUMB = C.TAGT_NUMB AND A.TAGT_HASH = C.TAGT_HASH WHERE 1 = 1
) Q ) P WHERE P.ROW_NUMB BETWEEN #{startRow} AND #{endRow} ORDER BY P.ROW_NUMB


   SELECT /* getRelatedComplaintList */

     FROM TH_CMPLNT C
LEFT JOIN TM_USERXM R
       ON R.USER_NUMB = C.USER_NUMB
LEFT JOIN TM_USERXM T
       ON T.USER_NUMB = C.TAGT_USER
    WHERE C.TAGT_TYPE = #{tagtType}
      AND C.TAGT_NUMB = #{tagtNumb}
      AND C.TAGT_HASH = #{tagtHash}
      AND C.CMPL_NUMB != #{cmplNumb}
 ORDER BY C.REGI_DATE DESC
        , C.CMPL_NUMB DESC
    LIMIT 10

SELECT /* getRelatedComplaintCnt */
       COUNT(1)
  FROM TH_CMPLNT C
 WHERE C.TAGT_TYPE = #{tagtType}
   AND C.TAGT_NUMB = #{tagtNumb}
   AND C.TAGT_HASH = #{tagtHash}
   AND C.CMPL_NUMB != #{cmplNumb}


SELECT /* getAutoActionCmplCnt */
       COUNT(1)
  FROM TH_CMPLNT C
 WHERE C.TAGT_TYPE = #{tagtType}
   AND C.TAGT_NUMB = #{tagtNumb}
   AND C.TAGT_HASH = #{tagtHash}
   AND C.CMPL_STAT != #{cmplRejected}

