UPDATE /* uptComplaint */
       TH_CMPLNT
   SET CMPL_STAT = #{update.cmplStat}
     , PROC_CNTN = #{update.procCntn,jdbcType=VARCHAR}
     , PROC_ADMN = #{procAdmn}
     , PROC_DATE = CASE WHEN #{update.cmplStat} IN (#{cmplActioned}, #{cmplRejected})
                             THEN CURRENT_TIMESTAMP(6)
                        ELSE NULL
                    END
     , UPDT_DATE = CURRENT_TIMESTAMP(6)
 WHERE CMPL_NUMB = #{cmplNumb}




UPDATE /* uptManualComplaints */
       TH_CMPLNT
   SET CMPL_STAT = #{cmplActioned}
     , PROC_CNTN = #{procCntn}
     , PROC_ADMN = #{procAdmn}
     , PROC_DATE = CURRENT_TIMESTAMP(6)
     , UPDT_DATE = CURRENT_TIMESTAMP(6)
 WHERE TAGT_TYPE = #{tagtType}
   AND TAGT_NUMB = #{tagtNumb}
   AND CMPL_STAT IN (#{cmplReceived}, #{cmplReviewing})

