SELECT /* getManualResultEvent */
       MIN(C.CMPL_NUMB) AS TRIG_CMPL, C.TAGT_TYPE, C.TAGT_NUMB, MAX(C.TAGT_HASH) AS TAGT_HASH
     , MAX(C.TAGT_USER) AS TAGT_USER
     , FN_GET_CODE_NAME(#{cmplTagt}, C.TAGT_TYPE, NULL) AS TAGT_NAME
     , COUNT(DISTINCT C.CMPL_RSON) AS RSON_CNTT, MIN(C.CMPL_RSON) AS RSON_CODE
     , FN_GET_CODE_NAME(#{cmplRsonGroup}, MIN(C.CMPL_RSON), NULL) AS RSON_NAME
     , MAX(C.PROC_DATE) AS PROC_DATE
  FROM TH_CMPLNT C
 WHERE C.TAGT_TYPE = #{tagtType}
   AND C.TAGT_NUMB = #{tagtNumb}
   AND C.CMPL_STAT = #{cmplActioned}
   AND C.PROC_CNTN = #{procCntn}
   AND C.PROC_ADMN = #{procAdmn}
 GROUP BY C.TAGT_TYPE, C.TAGT_NUMB

