/* setResultEvent */
INSERT INTO TH_CMREVT (
            TRIG_CMPL, TAGT_TYPE, TAGT_NUMB, TAGT_HASH, TAGT_USER, TAGT_NAME
          , RSON_SUMM, RSON_CODE, RSON_NAME, ACTN_TYPE, RPTR_CNTN, TGTR_CNTN, PROC_DATE
) VALUES (  #{trigCmpl}, #{tagtType}, #{tagtNumb}, #{tagtHash,jdbcType=CHAR}
          , #{tagtUser,jdbcType=NUMERIC}, #{tagtName}, #{rsonSumm}
          , #{rsonCode,jdbcType=VARCHAR}, #{rsonName}, #{actnType}
          , #{rptrCntn}, #{tgtrCntn}, #{procDate}
)





INSERT /* setReporterResult */
  INTO TH_CMRSLT (
       EVNT_NUMB, CMPL_NUMB, USER_NUMB, RCVR_TYPE, REGI_DATE
)
SELECT #{eventNumb}, C.CMPL_NUMB, C.USER_NUMB, #{receiverReporter}, CURRENT_TIMESTAMP(6)
  FROM TH_CMPLNT C
  JOIN TM_USERXM U ON U.USER_NUMB = C.USER_NUMB
                   AND U.USER_STAT IN (#{active}, #{suspended})
 WHERE C.CMPL_NUMB = #{cmplNumb}
   AND C.CMPL_STAT = #{cmplActioned}





INSERT /* setManualReporterResults */
  INTO TH_CMRSLT (
       EVNT_NUMB, CMPL_NUMB, USER_NUMB, RCVR_TYPE, REGI_DATE
)
SELECT #{eventNumb}, C.CMPL_NUMB, C.USER_NUMB, #{receiverReporter}, CURRENT_TIMESTAMP(6)
  FROM TH_CMPLNT C
  JOIN TM_USERXM U ON U.USER_NUMB = C.USER_NUMB
                   AND U.USER_STAT IN (#{active}, #{suspended})
 WHERE C.TAGT_TYPE = #{tagtType}
   AND C.TAGT_NUMB = #{tagtNumb}
   AND C.CMPL_STAT = #{cmplActioned}
   AND C.PROC_CNTN = #{procCntn}
   AND C.PROC_ADMN = #{procAdmn}

