SELECT /* getAutoActionTargetDtl */
       X.TAGT_CNTN
     , X.FILE_NUMB
     , X.STOR_NAME
     , X.FILE_PATH
  FROM (  SELECT COALESCE(P.REPT_CNTN, '') AS TAGT_CNTN
               , NULL AS FILE_NUMB
               , NULL AS STOR_NAME
               , NULL AS FILE_PATH
            FROM TM_REPORT P
           WHERE #{tagtType} = #{bookReport}
             AND P.REPT_NUMB = #{tagtNumb}
             AND P.USER_NUMB = #{userNumb}
             AND P.PUBC_YSNO = #{yes}
           UNION ALL
          SELECT COALESCE(R.REPL_CNTN, '') AS TAGT_CNTN
               , NULL AS FILE_NUMB
               , NULL AS STOR_NAME
               , NULL AS FILE_PATH
            FROM TB_REPLXX R
            JOIN TM_REPORT P
              ON P.REPT_NUMB = R.REPT_NUMB
             AND P.PUBC_YSNO = #{yes}
           WHERE #{tagtType} = #{reply}
             AND R.REPL_NUMB = #{tagtNumb}
             AND R.USER_NUMB = #{userNumb}
             AND COALESCE(R.DELT_YSNO, #{no}) = #{no}
           UNION ALL
          SELECT CONCAT('프로필 사진: ', COALESCE(F.ORIG_NAME, F.STOR_NAME, '파일명 없음')) AS TAGT_CNTN
               , F.FILE_NUMB
               , F.STOR_NAME
               , F.FILE_PATH
            FROM TM_USERXM U
            JOIN TM_FILEXM F
              ON F.FILE_NUMB = U.PROF_NUMB
           WHERE #{tagtType} = #{profileImage}
             AND U.USER_NUMB = #{tagtNumb}
             AND U.USER_NUMB = #{userNumb}
           UNION ALL
          SELECT CONCAT('배경사진: ', COALESCE(F.ORIG_NAME, F.STOR_NAME, '파일명 없음')) AS TAGT_CNTN
               , F.FILE_NUMB
               , F.STOR_NAME
               , F.FILE_PATH
            FROM TM_USERXM U
            JOIN TM_FILEXM F
              ON F.FILE_NUMB = U.BGIM_NUMB
           WHERE #{tagtType} = #{backgroundImage}
             AND U.USER_NUMB = #{tagtNumb}
             AND U.USER_NUMB = #{userNumb}
           UNION ALL
          SELECT U.INTR_CNTN AS TAGT_CNTN
               , NULL AS FILE_NUMB
               , NULL AS STOR_NAME
               , NULL AS FILE_PATH
            FROM TM_USERXM U
           WHERE #{tagtType} = #{introduction}
             AND U.USER_NUMB = #{tagtNumb}
             AND U.USER_NUMB = #{userNumb}
             AND NULLIF(TRIM(U.INTR_CNTN), '') IS NOT NULL
       ) X
 LIMIT 1

