UPDATE /* delTargetProfileImage */
       TM_USERXM
   SET PROF_NUMB = NULL
 WHERE USER_NUMB = #{userNumb}
   AND PROF_NUMB = #{fileNumb}

UPDATE /* delTargetBackgroundImage */
       TM_USERXM
   SET BGIM_NUMB = NULL
 WHERE USER_NUMB = #{userNumb}
   AND BGIM_NUMB = #{fileNumb}

